doc.code:
let x = 1;
let foo;
{
    let x = 2;
    foo = function() {
        return x;
    }
}

// in ECMAScript, foo() will return 2, but in Adaptive Script, it will return 1
foo();

// ECMAScript
let x = 1 // invalid in Adaptive Script (missing ;)
let y = 2;
'abc' // invalid in Adaptive Script (expression as statement)

try {
    throw "Something bad happened" { "code": 123 };
} catch (e) {
    print(e.message);
    print(e.data.code);
}

try {
    throw "boom";
} catch ({ message }) {
    print(message);
}

let y = "c";
let x = {
    a:   1,
    "b": 2,
    [y]: 3,
    ["Customer Name"]: "Ada"
};
assert(x.c === 3);
assert(x["Customer Name"] === "Ada");

let names = keys(x);
let a = [1, 2];
push(a, 3);
assert(at(a, -1) === 3);

/* JSON for storage or interchange */
stringify({ "a": 1, "b": true });

/* Adaptive form of a compiled value (not JSON) */
decompile(compile<script>(script("return 1+2;")));

/* Human listing (Fiddle / compile listing parameter) */
compile<script>(script("const x = 1;\nreturn x;"), 2);

/* Binary that is really text */
decode_to_string(encode_as_base64Binary("secret"));
